insert into principios_payload values ($principios_d662d8a10f85${"version":1,"material":{"id":"7d517d28-2e6e-503d-b72f-bc7421d6d492","slug":"constitucional-principios-fundamentais-federacao-republica","discipline":"Direito Constitucional","topic_label":"Princípios fundamentais","sort_order":1,"title":"Princípios fundamentais: Federação, República e autonomia dos entes","summary":"Aprenda a separar forma de Estado, forma e sistema de governo; diferencie autonomia de soberania e resolva casos sobre vínculo federativo, República e limites às emendas. Leia o texto-base, abra os casos resolvidos e pratique com 20 exercícios comentados.","body_md":"## O que você vai distinguir\n\nFederação responde **como o poder político se distribui no território**. República responde **como se organiza o governo e como seus titulares respondem pelo exercício do poder**. Presidencialismo é um sistema de governo; democracia diz respeito à participação e à legitimidade do poder. Essas categorias não são sinônimas.\n\n| Pergunta | Resposta para o Brasil | Leitura de apoio |\n| --- | --- | --- |\n| Qual é a forma de Estado? | Federação | CF, arts. 1º e 18 |\n| Qual é a forma de governo? | República | CF, arts. 1º e 34, VII, a |\n| Qual é o sistema de governo? | Presidencialismo | CF, arts. 76 e 77 |\n| Quem é a fonte do poder político? | O povo, com exercício representativo ou direto nos termos da Constituição | CF, art. 1º, parágrafo único |\n\n## Leia a base constitucional\n\n**Art. 1º — trecho inicial:** “A República Federativa do Brasil, formada pela união indissolúvel dos Estados e Municípios e do Distrito Federal, constitui-se em Estado Democrático de Direito”.\n\n**Art. 18 — caput:** “A organização político-administrativa da República Federativa do Brasil compreende a União, os Estados, o Distrito Federal e os Municípios, todos autônomos, nos termos desta Constituição.”\n\nEsses recortes não substituem a leitura integral. Consulte os artigos na [Constituição compilada oficial](https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm).\n\n## Federação: autonomia sem direito de separação\n\nA Constituição distribui competências entre União, estados, Distrito Federal e municípios. Eles possuem autonomia constitucional; não são quatro categorias de países soberanos. A soberania é fundamento da República Federativa do Brasil.\n\nA **União** é um ente da organização interna. A **República Federativa do Brasil** é o Estado brasileiro. Confundir os dois nomes costuma transformar uma afirmação correta sobre soberania em uma conclusão errada sobre hierarquia entre entes.\n\nAutonomia não significa liberdade para contrariar a Constituição. Os estados elaboram constituições próprias dentro dos limites federais (art. 25); os municípios se regem por leis orgânicas (art. 29); o Distrito Federal tem lei orgânica e não pode ser dividido em municípios (art. 32).\n\n**Indissolubilidade:** um estado não pode tornar-se país independente por decisão unilateral. Isso não impede toda alteração interna do mapa: incorporação, subdivisão e desmembramento de estados têm condições próprias no art. 18, § 3º, incluindo plebiscito da população diretamente interessada e lei complementar do Congresso Nacional. Alterar limites internos e romper a Federação são situações diferentes.\n\n**Territórios federais:** integram a União (art. 18, § 2º). Não devem ser acrescentados ao rol de entes autônomos do caput.\n\n## República: mandato, controle e responsabilidade\n\nA lógica republicana afasta a ideia de tratar o cargo político como patrimônio pessoal ou hereditário. Para estudar suas consequências concretas, associe eleição e duração de mandatos à responsabilidade dos governantes e ao dever de prestar contas, sem presumir que todo cargo público seja eletivo.\n\nA Constituição prevê mandatos políticos de duração definida e mecanismos de responsabilização. Os arts. 34, VII, a e d, protegem a forma republicana, o regime democrático e a prestação de contas. O art. 85 trata dos crimes de responsabilidade do Presidente da República.\n\n**Cuidado:** eleição não é autorização para agir acima da Constituição. A escolha popular de um governante não elimina os controles nem converte recursos públicos em propriedade do eleito.\n\n## Proteção da Federação e da democracia\n\nO art. 60, § 4º, impede deliberar proposta de emenda **tendente a abolir** a forma federativa de Estado. Também protege o voto direto, secreto, universal e periódico; a separação dos Poderes; e os direitos e garantias individuais.\n\nNão é correto concluir que toda regra sobre competências federativas seja imutável. A proteção recai contra a tendência de abolir a forma federativa, e não contra qualquer mudança compatível com ela.\n\nA expressão “forma republicana” não aparece literalmente nessa lista. Esse dado de leitura não autoriza afirmar que qualquer alteração de governo seja constitucional: ainda é preciso examinar os demais limites, especialmente o voto periódico e o regime democrático.\n\n## Como resolver uma questão deste assunto\n\n1. Identifique a categoria cobrada: Estado, governo, sistema de governo ou regime político.\n2. Veja se o enunciado troca **autonomia** por **soberania**.\n3. Diferencie rearranjo territorial interno de separação do país.\n4. Quando houver emenda, confira se ela apenas modifica uma regra ou tende a abolir uma proteção constitucional.\n5. Use o dispositivo pertinente; não transfira uma regra penal ou internacional para a teoria geral do Estado.\n\n## Duas correções conceituais importantes\n\n**Povo, população e nação:** são categorias distintas. Em uma introdução, povo se relaciona ao vínculo jurídico-político; população é expressão demográfica; nação se relaciona a vínculos históricos e culturais. Isso não significa que toda pessoa presente no território possa exercer todos os direitos políticos. Para os requisitos constitucionais específicos, continue em [Nacionalidade](/dashboard/library/constitucional-nacionalidade-medidas-retirada) e [Direitos políticos](/dashboard/library/constitucional-direitos-politicos-elegibilidade).\n\n**Embarcações e aeronaves:** o Código Penal, art. 5º, § 1º, prevê extensão do território **para efeitos penais**, com requisitos próprios. Essa técnica de aplicação da lei penal não significa que a embarcação transforme fisicamente o território estrangeiro em território brasileiro. O estudo completo fica em [Lei penal no espaço](/dashboard/library/penal-lei-no-espaco), evitando repetir esse conteúdo aqui.\n\nAs classificações doutrinárias históricas do federalismo podem variar conforme o autor e a banca. Para este módulo, priorize o que o texto constitucional permite verificar: autonomia dos entes, repartição de competências, vínculo indissolúvel e limites à reforma.\n","contest_name":"Polícia Militar de Santa Catarina — Soldado — 2023","syllabus_topic_order":1,"source_note":"Explicações, casos e exercícios com redação própria. Textos oficiais consultados em 24/10/2026. Vínculo curricular: PMSC Soldado 2023, item 1.1. A aplicação a outros concursos depende do edital e de sua data de corte. Os exercícios são de fixação; não reproduzem questões de uma banca.","legal_basis":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"Código Penal — art. 5º, delimitação da extensão para efeitos penais","url":"https://www.planalto.gov.br/ccivil_03/Decreto-Lei/Del2848compilado.htm"}],"law_version_checked_at":"2026-10-24T20:38:35.690514+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T20:38:35.690514+00:00","quiz":[{"q":"Uma comissão propõe chamar de “soberania municipal” a competência de um município para elaborar sua lei orgânica. Essa denominação descreve corretamente o vínculo constitucional do município.","a":false,"why":"O município é autônomo, não soberano. A elaboração da lei orgânica expressa autonomia de organização; a soberania é fundamento da República Federativa do Brasil. Exemplo: o município organiza sua atuação dentro dos limites constitucionais, sem se tornar país independente. Base: CF, Art. 1º; Art. 18."},{"q":"Em uma ficha de revisão, a linha “distribuição territorial do poder político” deve ser associada à Federação, enquanto a linha “forma de governo brasileira” deve ser associada à República.","a":true,"why":"As categorias respondem a perguntas diferentes. Exemplo: escrever “república” como forma de Estado troca a organização do governo pela distribuição territorial do poder. Base: CF, Art. 1º; Art. 18."},{"q":"Dois estados pretendem incorporar-se entre si. Como a Constituição afirma que a Federação é indissolúvel, qualquer incorporação interna é proibida, mesmo quando cumpridas as condições constitucionais.","a":false,"why":"O art. 18, § 3º, admite reorganizações internas sob condições próprias. É necessário distinguir incorporação dentro do Brasil de separação para formar um país independente. Base: CF, Art. 18, § 3º."},{"q":"Um plebiscito local favorável basta para que um estado deixe o Brasil e se torne país independente, pois autonomia inclui direito unilateral de secessão.","a":false,"why":"O vínculo federativo é indissolúvel. O plebiscito previsto para reorganização interna não é autorização para romper o país. Mesmo no rearranjo interno existem outras condições, como lei complementar do Congresso Nacional. Base: CF, Art. 1º; Art. 18, § 3º."},{"q":"Ao revisar um organograma, a estudante retira “Territórios Federais” da lista de entes autônomos e os posiciona como integrantes da União. A correção corresponde ao art. 18.","a":true,"why":"O caput enumera União, estados, Distrito Federal e municípios como autônomos; o § 2º dispõe que os territórios integram a União. Não se cria uma quinta categoria de ente federativo autônomo. Base: CF, Art. 18, § 2º."},{"q":"Um projeto prevê dividir o Distrito Federal em municípios, justificando que isso seria simples exercício de sua autonomia. A justificativa afasta a vedação constitucional.","a":false,"why":"O art. 32 veda expressamente a divisão do Distrito Federal em municípios. Autonomia não permite contrariar essa restrição; a organização distrital tem disciplina constitucional própria. Base: CF, Art. 32."},{"q":"Uma constituição estadual pode organizar o estado, mas não pode afastar os princípios impostos pela Constituição Federal sob o argumento de que ambos os textos têm a mesma liberdade de criação.","a":true,"why":"O art. 25 condiciona a organização estadual aos princípios da Constituição Federal. A capacidade de auto-organização não equivale a poder constituinte originário soberano. Base: CF, Art. 25."},{"q":"Para demonstrar autonomia municipal, o enunciado afirma que o município deve se reger por uma constituição municipal promulgada pelo governador. A descrição está correta.","a":false,"why":"O município se rege por lei orgânica aprovada e promulgada pela Câmara Municipal, com as condições do art. 29. Não é constituição estadual nem ato do governador. Base: CF, Art. 29."},{"q":"Em um resumo, a União aparece como um ente da organização político-administrativa, e não como sinônimo de toda a República Federativa do Brasil. Essa distinção evita confundir organização interna e Estado brasileiro.","a":true,"why":"O art. 18 inclui a União ao lado de estados, Distrito Federal e municípios. A República Federativa do Brasil compreende o conjunto da organização, não apenas esse ente. Base: CF, Art. 18."},{"q":"Uma proposta declara expressamente extinguir a forma federativa. Se atingir três quintos dos votos em dois turnos de cada Casa, o quórum supera a limitação material constitucional.","a":false,"why":"Cumprir o procedimento não afasta uma cláusula pétrea. O § 4º impede deliberar proposta tendente a abolir a forma federativa; quórum qualificado não transforma o conteúdo proibido em conteúdo permitido. Base: CF, Art. 60, § 4º, I."},{"q":"A proteção da forma federativa não permite concluir que toda alteração pontual de competência entre entes seja automaticamente proibida. É preciso examinar se a proposta tende a abolir essa forma de Estado.","a":true,"why":"A Constituição protege contra a abolição, sem petrificar indistintamente cada regra de organização. Exemplo: avaliar uma modificação de competência exige analisar seu conteúdo e efeito, não apenas sua existência. Base: CF, Art. 60, § 4º, I."},{"q":"Ao constatar que “forma republicana” não está escrita literalmente no rol do § 4º, um candidato conclui que uma emenda pode, sem examinar mais nada, eliminar eleições periódicas e instituir cargo político hereditário.","a":false,"why":"A conclusão ignora limites expressos, como a proteção do voto direto, secreto, universal e periódico. A ausência de uma expressão na lista não dispensa examinar as demais garantias constitucionais. Base: CF, Art. 60, § 4º."},{"q":"Para explicar a relação entre república e controle, um quadro associa a forma republicana à prestação de contas da administração, ambas protegidas no art. 34, VII.","a":true,"why":"O dispositivo contém esses princípios em alíneas distintas. Exemplo: a eleição de um governante não elimina a exigência de prestar contas sobre a administração pública. Base: CF, Art. 34, VII, a e d."},{"q":"Um governante afirma que vencer uma eleição elimina qualquer responsabilidade por atos que atentem contra a Constituição. Essa consequência decorre do princípio republicano.","a":false,"why":"A Constituição prevê responsabilização, incluindo crimes de responsabilidade do Presidente no art. 85. Legitimidade eleitoral não cria imunidade absoluta nem coloca o governante acima da Constituição. Base: CF, Art. 85."},{"q":"Um material que explique a origem popular do poder somente pela eleição de representantes está incompleto se excluir toda possibilidade de exercício direto prevista na Constituição.","a":true,"why":"O parágrafo único contempla representantes eleitos ou exercício direto, nos termos constitucionais. Isso não significa que qualquer decisão popular, sem observar tais termos, produza todo efeito pretendido. Base: CF, Art. 1º, parágrafo único."},{"q":"Em uma tabela, “presidencialismo” é indicado como forma de Estado e “Federação” como sistema de governo. As duas classificações estão corretas.","a":false,"why":"As posições estão invertidas: Federação é forma de Estado; presidencialismo é sistema de governo. Os arts. 76 e 77 dão suporte ao estudo da Presidência, não mudam a categoria da Federação. Base: CF, Art. 76; Art. 77."},{"q":"Um esquema que apresenta Legislativo, Executivo e Judiciário como independentes e harmônicos não autoriza concluir que um deles pode eliminar os outros por decisão unilateral.","a":true,"why":"O art. 2º exige independência e harmonia, não supressão de Poderes. A separação também é protegida pelo art. 60, § 4º, III. Base: CF, Art. 2º."},{"q":"A Constituição trataria a forma republicana como assunto sem proteção específica, pois o art. 34, VII, somente se refere a questões financeiras.","a":false,"why":"A alínea a menciona forma republicana, sistema representativo e regime democrático. O dispositivo não se restringe a finanças, ainda que também contenha previsões sobre prestação de contas. Base: CF, Art. 34, VII, a."},{"q":"O Distrito Federal acumula competências legislativas reservadas aos estados e aos municípios, sem que isso o transforme em dois entes separados ou permita sua divisão municipal.","a":true,"why":"O art. 32, § 1º, atribui essas competências ao próprio Distrito Federal, enquanto o caput veda sua divisão em municípios. Acumular competências não altera essa identidade. Base: CF, Art. 18; Art. 32, § 1º."},{"q":"Uma emenda deve ser examinada quanto ao conteúdo protegido mesmo quando mantém o nome “Federação”: o rótulo, isoladamente, não comprova respeito à forma federativa nem ao voto periódico.","a":true,"why":"A proteção alcança propostas tendentes a abolir as garantias, e não apenas a troca de seus nomes. O exame precisa considerar os efeitos normativos concretos da alteração proposta. Base: CF, Art. 60, § 4º, I e II."}],"flashcards":[{"f":"Qual é a forma de Estado brasileira?","b":"Federação. Trata da distribuição territorial do poder político."},{"f":"Qual é a forma de governo brasileira?","b":"República. Não confundir com Federação nem com presidencialismo."},{"f":"Os entes federativos são soberanos?","b":"São autônomos nos termos do art. 18. A soberania é fundamento da República Federativa do Brasil."},{"f":"A indissolubilidade proíbe toda alteração interna de limites?","b":"Não. O art. 18 prevê condições para reorganizações internas; isso não é secessão."},{"f":"O Distrito Federal pode ser dividido em municípios?","b":"Não. A vedação está no art. 32."},{"f":"A forma republicana está escrita literalmente no rol do art. 60, § 4º?","b":"Não. Isso não afasta os demais limites constitucionais, como o voto periódico e a separação dos Poderes."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-principios-fundamentais-federacao-republica","subject":"Direito Constitucional","topic_label":"Princípios fundamentais","syllabus_topic_id":"5b5a7f1e-44bf-4cab-903e-199eacd65578","checked_at":"2026-10-24T20:38:35.690514+00:00","scope":"Exercícios de fixação autorais, conferidos com a Constituição compilada oficial, vinculados ao tópico atual cadastrado da edição PMSC 2023. A atualização para estudo não modifica a data de corte de provas históricas. Não são questões atribuídas à banca ou à apostila enviada.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"82a054357e7b18f0a2f1d2c1d584a1ef77ff40842cf7297d9ff9fc78f9929349","checked_at":"2026-10-24T20:38:35.690514+00:00"}],"items":[{"q":"Uma comissão propõe chamar de “soberania municipal” a competência de um município para elaborar sua lei orgânica. Essa denominação descreve corretamente o vínculo constitucional do município.","a":false,"why":"O município é autônomo, não soberano. A elaboração da lei orgânica expressa autonomia de organização; a soberania é fundamento da República Federativa do Brasil. Exemplo: o município organiza sua atuação dentro dos limites constitucionais, sem se tornar país independente. Base: CF, Art. 1º; Art. 18.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 1º; Art. 18","origin":"authored_official_constitution_case"},{"q":"Em uma ficha de revisão, a linha “distribuição territorial do poder político” deve ser associada à Federação, enquanto a linha “forma de governo brasileira” deve ser associada à República.","a":true,"why":"As categorias respondem a perguntas diferentes. Exemplo: escrever “república” como forma de Estado troca a organização do governo pela distribuição territorial do poder. Base: CF, Art. 1º; Art. 18.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 1º; Art. 18","origin":"authored_official_constitution_case"},{"q":"Dois estados pretendem incorporar-se entre si. Como a Constituição afirma que a Federação é indissolúvel, qualquer incorporação interna é proibida, mesmo quando cumpridas as condições constitucionais.","a":false,"why":"O art. 18, § 3º, admite reorganizações internas sob condições próprias. É necessário distinguir incorporação dentro do Brasil de separação para formar um país independente. Base: CF, Art. 18, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 18, § 3º","origin":"authored_official_constitution_case"},{"q":"Um plebiscito local favorável basta para que um estado deixe o Brasil e se torne país independente, pois autonomia inclui direito unilateral de secessão.","a":false,"why":"O vínculo federativo é indissolúvel. O plebiscito previsto para reorganização interna não é autorização para romper o país. Mesmo no rearranjo interno existem outras condições, como lei complementar do Congresso Nacional. Base: CF, Art. 1º; Art. 18, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 1º; Art. 18, § 3º","origin":"authored_official_constitution_case"},{"q":"Ao revisar um organograma, a estudante retira “Territórios Federais” da lista de entes autônomos e os posiciona como integrantes da União. A correção corresponde ao art. 18.","a":true,"why":"O caput enumera União, estados, Distrito Federal e municípios como autônomos; o § 2º dispõe que os territórios integram a União. Não se cria uma quinta categoria de ente federativo autônomo. Base: CF, Art. 18, § 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 18, § 2º","origin":"authored_official_constitution_case"},{"q":"Um projeto prevê dividir o Distrito Federal em municípios, justificando que isso seria simples exercício de sua autonomia. A justificativa afasta a vedação constitucional.","a":false,"why":"O art. 32 veda expressamente a divisão do Distrito Federal em municípios. Autonomia não permite contrariar essa restrição; a organização distrital tem disciplina constitucional própria. Base: CF, Art. 32.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 32","origin":"authored_official_constitution_case"},{"q":"Uma constituição estadual pode organizar o estado, mas não pode afastar os princípios impostos pela Constituição Federal sob o argumento de que ambos os textos têm a mesma liberdade de criação.","a":true,"why":"O art. 25 condiciona a organização estadual aos princípios da Constituição Federal. A capacidade de auto-organização não equivale a poder constituinte originário soberano. Base: CF, Art. 25.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 25","origin":"authored_official_constitution_case"},{"q":"Para demonstrar autonomia municipal, o enunciado afirma que o município deve se reger por uma constituição municipal promulgada pelo governador. A descrição está correta.","a":false,"why":"O município se rege por lei orgânica aprovada e promulgada pela Câmara Municipal, com as condições do art. 29. Não é constituição estadual nem ato do governador. Base: CF, Art. 29.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 29","origin":"authored_official_constitution_case"},{"q":"Em um resumo, a União aparece como um ente da organização político-administrativa, e não como sinônimo de toda a República Federativa do Brasil. Essa distinção evita confundir organização interna e Estado brasileiro.","a":true,"why":"O art. 18 inclui a União ao lado de estados, Distrito Federal e municípios. A República Federativa do Brasil compreende o conjunto da organização, não apenas esse ente. Base: CF, Art. 18.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 18","origin":"authored_official_constitution_case"},{"q":"Uma proposta declara expressamente extinguir a forma federativa. Se atingir três quintos dos votos em dois turnos de cada Casa, o quórum supera a limitação material constitucional.","a":false,"why":"Cumprir o procedimento não afasta uma cláusula pétrea. O § 4º impede deliberar proposta tendente a abolir a forma federativa; quórum qualificado não transforma o conteúdo proibido em conteúdo permitido. Base: CF, Art. 60, § 4º, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 60, § 4º, I","origin":"authored_official_constitution_case"},{"q":"A proteção da forma federativa não permite concluir que toda alteração pontual de competência entre entes seja automaticamente proibida. É preciso examinar se a proposta tende a abolir essa forma de Estado.","a":true,"why":"A Constituição protege contra a abolição, sem petrificar indistintamente cada regra de organização. Exemplo: avaliar uma modificação de competência exige analisar seu conteúdo e efeito, não apenas sua existência. Base: CF, Art. 60, § 4º, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 60, § 4º, I","origin":"authored_official_constitution_case"},{"q":"Ao constatar que “forma republicana” não está escrita literalmente no rol do § 4º, um candidato conclui que uma emenda pode, sem examinar mais nada, eliminar eleições periódicas e instituir cargo político hereditário.","a":false,"why":"A conclusão ignora limites expressos, como a proteção do voto direto, secreto, universal e periódico. A ausência de uma expressão na lista não dispensa examinar as demais garantias constitucionais. Base: CF, Art. 60, § 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 60, § 4º","origin":"authored_official_constitution_case"},{"q":"Para explicar a relação entre república e controle, um quadro associa a forma republicana à prestação de contas da administração, ambas protegidas no art. 34, VII.","a":true,"why":"O dispositivo contém esses princípios em alíneas distintas. Exemplo: a eleição de um governante não elimina a exigência de prestar contas sobre a administração pública. Base: CF, Art. 34, VII, a e d.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 34, VII, a e d","origin":"authored_official_constitution_case"},{"q":"Um governante afirma que vencer uma eleição elimina qualquer responsabilidade por atos que atentem contra a Constituição. Essa consequência decorre do princípio republicano.","a":false,"why":"A Constituição prevê responsabilização, incluindo crimes de responsabilidade do Presidente no art. 85. Legitimidade eleitoral não cria imunidade absoluta nem coloca o governante acima da Constituição. Base: CF, Art. 85.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 85","origin":"authored_official_constitution_case"},{"q":"Um material que explique a origem popular do poder somente pela eleição de representantes está incompleto se excluir toda possibilidade de exercício direto prevista na Constituição.","a":true,"why":"O parágrafo único contempla representantes eleitos ou exercício direto, nos termos constitucionais. Isso não significa que qualquer decisão popular, sem observar tais termos, produza todo efeito pretendido. Base: CF, Art. 1º, parágrafo único.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 1º, parágrafo único","origin":"authored_official_constitution_case"},{"q":"Em uma tabela, “presidencialismo” é indicado como forma de Estado e “Federação” como sistema de governo. As duas classificações estão corretas.","a":false,"why":"As posições estão invertidas: Federação é forma de Estado; presidencialismo é sistema de governo. Os arts. 76 e 77 dão suporte ao estudo da Presidência, não mudam a categoria da Federação. Base: CF, Art. 76; Art. 77.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 76; Art. 77","origin":"authored_official_constitution_case"},{"q":"Um esquema que apresenta Legislativo, Executivo e Judiciário como independentes e harmônicos não autoriza concluir que um deles pode eliminar os outros por decisão unilateral.","a":true,"why":"O art. 2º exige independência e harmonia, não supressão de Poderes. A separação também é protegida pelo art. 60, § 4º, III. Base: CF, Art. 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 2º","origin":"authored_official_constitution_case"},{"q":"A Constituição trataria a forma republicana como assunto sem proteção específica, pois o art. 34, VII, somente se refere a questões financeiras.","a":false,"why":"A alínea a menciona forma republicana, sistema representativo e regime democrático. O dispositivo não se restringe a finanças, ainda que também contenha previsões sobre prestação de contas. Base: CF, Art. 34, VII, a.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 34, VII, a","origin":"authored_official_constitution_case"},{"q":"O Distrito Federal acumula competências legislativas reservadas aos estados e aos municípios, sem que isso o transforme em dois entes separados ou permita sua divisão municipal.","a":true,"why":"O art. 32, § 1º, atribui essas competências ao próprio Distrito Federal, enquanto o caput veda sua divisão em municípios. Acumular competências não altera essa identidade. Base: CF, Art. 18; Art. 32, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 18; Art. 32, § 1º","origin":"authored_official_constitution_case"},{"q":"Uma emenda deve ser examinada quanto ao conteúdo protegido mesmo quando mantém o nome “Federação”: o rótulo, isoladamente, não comprova respeito à forma federativa nem ao voto periódico.","a":true,"why":"A proteção alcança propostas tendentes a abolir as garantias, e não apenas a troca de seus nomes. O exame precisa considerar os efeitos normativos concretos da alteração proposta. Base: CF, Art. 60, § 4º, I e II.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 60, § 4º, I e II","origin":"authored_official_constitution_case"}]},"legal_review":{"checked_at":"2026-10-24T20:38:35.690514+00:00","scope":"Conferência dos dispositivos constitucionais utilizados e do art. 5º do Código Penal. As explicações são elaboração própria, sem reprodução da redação didática ou dos exercícios da apostila. Não certifica auditoria de toda a Constituição ou jurisprudência.","sources":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"82a054357e7b18f0a2f1d2c1d584a1ef77ff40842cf7297d9ff9fc78f9929349"},{"title":"Código Penal — art. 5º, delimitação da extensão para efeitos penais","url":"https://www.planalto.gov.br/ccivil_03/Decreto-Lei/Del2848compilado.htm","sha256":"7f567d6359fa6650072427ae9fcfc4f20adfa81f04d0c861831110144820ae92"}],"changes":[],"corrections":["Separada autonomia dos entes de soberania do Estado brasileiro.","Diferenciada a extensão territorial para efeitos penais de território físico.","Evitada a conclusão de que ausência literal da forma republicana no art. 60 permite qualquer reforma."]}},"enrichment":{"id":"f6c88d53-75ae-5647-b6c7-b50e815b93ca","material_slug":"constitucional-principios-fundamentais-federacao-republica","version":"2026-10-24-principios-v1","source_body_sha256":"5cc997d1bac9f783e60e6fb11f7bf0047a912b7e5ab507d1f5af9ecec9b6d8a9","content":{"cases":[{"id":"autonomia","title":"O estado pode transformar autonomia em soberania?","scenario":"Uma assembleia estadual pretende declarar o estado um país independente após consulta local. O projeto usa a expressão “exercício da autonomia”.","question":"A consulta local autoriza romper a Federação?","steps":["Identifique o efeito pretendido: deixar o Brasil, e não apenas mudar um limite interno.","Leia a união indissolúvel no art. 1º e a autonomia nos termos da Constituição no art. 18.","Não use a consulta para rearranjo interno como autorização de secessão."],"conclusion":"Não. A autonomia constitucional não inclui direito unilateral de separar-se do país.","pitfall":"Tratar qualquer aprovação popular como autorização para ignorar as condições constitucionais.","variation":{"scenario":"Os estados querem incorporar-se entre si, permanecendo no Brasil.","answer":"O art. 18, § 3º, admite essa hipótese sob condições, como plebiscito da população diretamente interessada e lei complementar do Congresso. Permanecer na Federação muda a análise, sem dispensar requisitos."},"articles":["Art. 1º","Art. 18"]},{"id":"categorias","title":"Três etiquetas, três perguntas","scenario":"Um aplicativo de revisão mostra: forma de Estado = República; forma de governo = presidencialismo; sistema de governo = Federação.","question":"Como corrigir as três linhas?","steps":["Associe distribuição territorial do poder à forma de Estado.","Associe República à forma de governo.","Associe presidencialismo ao sistema de governo e leia os arts. 76 e 77."],"conclusion":"Forma de Estado: Federação. Forma de governo: República. Sistema de governo: presidencialismo.","pitfall":"Usar as três palavras como se fossem respostas intercambiáveis.","variation":{"scenario":"A pergunta troca “sistema de governo” por “titularidade do poder político”.","answer":"Agora a referência é o povo, conforme o art. 1º, parágrafo único. A resposta não é o nome de um sistema de governo."},"articles":["Art. 1º","Art. 18","Art. 76","Art. 77"]},{"id":"reforma","title":"Um quórum alto resolve qualquer emenda?","scenario":"Uma proposta obtém apoio para extinguir a forma federativa e sustenta que respeitar dois turnos e três quintos em cada Casa seria suficiente.","question":"O procedimento formal elimina a vedação material?","steps":["Separe requisitos procedimentais de limites de conteúdo.","Localize a forma federativa no art. 60, § 4º, I.","Confira a expressão “tendente a abolir”, que não se limita à mudança de um nome."],"conclusion":"Não. A limitação material continua aplicável mesmo com apoio suficiente para o procedimento de votação.","pitfall":"Imaginar que quantidade de votos elimina todos os limites ao poder de reforma.","variation":{"scenario":"A proposta apenas altera uma competência específica, mantendo a estrutura federativa.","answer":"Não se presume proibição de toda modificação. Examine se o efeito tende a abolir a forma federativa, além de conferir os demais requisitos constitucionais."},"articles":["Art. 60"]},{"id":"republica","title":"Eleição dispensa prestar contas?","scenario":"Um governante afirma que a vitória eleitoral lhe permite administrar recursos públicos sem prestar contas e impede qualquer responsabilização constitucional.","question":"A eleição produz essas duas consequências?","steps":["Reconheça que legitimidade eleitoral não elimina o dever de observar a Constituição.","Consulte a proteção da forma republicana e da prestação de contas no art. 34, VII.","Observe no art. 85 a previsão de crimes de responsabilidade do Presidente, sem presumir culpa em um caso real."],"conclusion":"Não. Mandato eletivo, dever de prestar contas e mecanismos de responsabilização convivem no regime constitucional.","pitfall":"Confundir origem democrática do mandato com imunidade absoluta ou propriedade privada do cargo.","variation":{"scenario":"O governante apenas questiona uma acusação e exerce seu direito de defesa.","answer":"Exercer defesa é compatível com a Constituição. A existência de responsabilidade não dispensa processo, competência e garantias aplicáveis."},"articles":["Art. 34","Art. 85"]}],"illustrations":[]},"sources":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"checked_at":"2026-10-24T20:38:35.690514+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T20:38:35.690514+00:00"},"syllabus_topic":{"id":"5b5a7f1e-44bf-4cab-903e-199eacd65578","block_name":"Prova objetiva","created_at":"2026-10-18T02:49:43.334855+00:00","discipline":"Direito Constitucional","edition_id":"70d4357a-1cd9-4bd8-adf1-b717adc46059","topic_text":"Constituição de 1988: princípios fundamentais; aplicabilidade das normas constitucionais; direitos e garantias fundamentais, nacionalidade, direitos políticos e partidos; organização político-administrativa (Estado federal); administração pública e servidores.","topic_order":1,"content_status":"current"},"edition":{"id":"70d4357a-1cd9-4bd8-adf1-b717adc46059","status":"active","role_name":"Soldado da Polícia Militar","source_id":"61d11008-7d69-47eb-88ea-3bfe64ba8edb","created_at":"2026-10-18T02:49:43.334855+00:00","exam_board":"CEBRASPE","contest_name":"Polícia Militar de Santa Catarina","contest_year":2023},"sources":[{"title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"82a054357e7b18f0a2f1d2c1d584a1ef77ff40842cf7297d9ff9fc78f9929349","checked_at":"2026-10-24T20:38:35.690514+00:00"},{"title":"Código Penal — art. 5º, delimitação da extensão para efeitos penais","url":"https://www.planalto.gov.br/ccivil_03/Decreto-Lei/Del2848compilado.htm","sha256":"7f567d6359fa6650072427ae9fcfc4f20adfa81f04d0c861831110144820ae92","checked_at":"2026-10-24T20:38:34.437648+00:00"},{"title":"Edital PMSC Soldado 2023 — Noções de Direito Constitucional, item 1.1","url":"https://cdn.cebraspe.org.br/concursos/PM_SC_23_SOLDADO/arquivos/Ed_2_2022_PMSC_Abertura_Soldado_atualizado.pdf","sha256":"707f23f56d7a24e5f12997112d6082accd09c956d732915d89d565744d659608","checked_at":"2026-10-24T20:38:35.690514+00:00"}]}$principios_d662d8a10f85$::jsonb);
do $guard$
declare p jsonb; m public.study_materials; en public.study_material_enrichments;
begin
 select payload into p from principios_payload;
 if not exists (select 1 from public.user_roles where user_id=(p#>>'{material,reviewed_by}')::uuid and role::text='admin') then
  raise exception 'Responsável pela publicação não é administrador. Nada aplicado.'; end if;
 if not exists (select 1 from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id join public.content_sources s on s.id=e.source_id
   where t.id=(p#>>'{syllabus_topic,id}')::uuid and t.topic_text=p#>>'{syllabus_topic,topic_text}' and t.content_status='current' and e.status='active'
     and s.is_official and s.source_type='edital' and s.url=p#>>'{sources,2,url}') then
  raise exception 'Vínculo com o edital oficial foi alterado. Nada aplicado.'; end if;
 if jsonb_array_length(p#>'{material,quiz}')<>20 or jsonb_array_length(p#>'{material,practice_review,items}')<>20 or jsonb_array_length(p#>'{enrichment,content,cases}')<>4 then
  raise exception 'Pacote incompleto. Nada aplicado.'; end if;
 select * into m from public.study_materials where slug=p#>>'{material,slug}';
 if found and (not (to_jsonb(m) @> ((p->'material') - 'law_version_checked_at' - 'reviewed_at')) or m.law_version_checked_at<>(p#>>'{material,law_version_checked_at}')::timestamptz or m.reviewed_at<>(p#>>'{material,reviewed_at}')::timestamptz) then
  raise exception 'Material concorrente diferente. Não foi sobrescrito.'; end if;
 select * into en from public.study_material_enrichments where material_slug=p#>>'{material,slug}' and version=p#>>'{enrichment,version}';
 if found and not (to_jsonb(en) @> ((p->'enrichment') - 'checked_at' - 'reviewed_at')) then
  raise exception 'Casos existentes diferentes. Não foram sobrescritos.'; end if;
end $guard$;
insert into public.content_sources(source_type,title,issuer,url,status,is_official,checked_at,notes)
select case when ordinality=1 then 'constituicao' else 'lei' end,s->>'title','Presidência da República — Planalto',s->>'url','vigente',true,(s->>'checked_at')::timestamptz,
 'Conferência limitada aos dispositivos utilizados no módulo de princípios fundamentais; não certifica auditoria integral do diploma. SHA-256 do documento consultado: '||(s->>'sha256')
from principios_payload p cross join lateral jsonb_array_elements(p.payload->'sources') with ordinality s(s,ordinality)
where ordinality<=2
on conflict(url) do nothing;
insert into public.study_materials (id,slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,law_version_checked_at,content_status,reviewed_by,reviewed_at,quiz,flashcards,practice_review,legal_review)
select r.id,r.slug,r.discipline,r.topic_label,r.sort_order,r.title,r.summary,r.body_md,r.contest_name,r.syllabus_topic_order,r.source_note,r.legal_basis,r.law_version_checked_at,r.content_status,r.reviewed_by,r.reviewed_at,r.quiz,r.flashcards,r.practice_review,r.legal_review from principios_payload p cross join lateral jsonb_populate_record(null::public.study_materials,p.payload->'material') r
on conflict (slug) do nothing;
insert into public.study_material_enrichments (id,material_slug,version,source_body_sha256,content,sources,checked_at,status,reviewed_by,reviewed_at)
select r.id,r.material_slug,r.version,r.source_body_sha256,r.content,r.sources,r.checked_at,r.status,r.reviewed_by,r.reviewed_at from principios_payload p cross join lateral jsonb_populate_record(null::public.study_material_enrichments,p.payload->'enrichment') r
on conflict (material_slug,version) do nothing;
do $verify$
declare p jsonb;
begin
 select payload into p from principios_payload;
 if not exists(select 1 from public.study_materials m where m.slug=p#>>'{material,slug}' and m.content_status='active' and m.body_md=p#>>'{material,body_md}' and m.quiz=p#>'{material,quiz}' and m.practice_review=p#>'{material,practice_review}') then raise exception 'Falha na conferência final do material.'; end if;
 if not exists(select 1 from public.study_material_enrichments e where e.id=(p#>>'{enrichment,id}')::uuid and e.status='active' and e.content=p#>'{enrichment,content}' and e.source_body_sha256=p#>>'{enrichment,source_body_sha256}') then raise exception 'Falha na conferência final dos casos.'; end if;
end $verify$;
select m.slug,m.content_status,jsonb_array_length(m.quiz) as local_exercises,jsonb_array_length(e.content->'cases') as worked_cases
from public.study_materials m join public.study_material_enrichments e on e.material_slug=m.slug cross join principios_payload p
where m.slug=p.payload#>>'{material,slug}' and e.version=p.payload#>>'{enrichment,version}';
commit;
